head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gLdMktTp;
scwin.gParamObj = new Array(1);
scwin.vScrenID = 'ULDSTF39003.xml';X < !정보--;
셋팅-- > function() {
    //rdo_mkt_tp_cd.value =  frame.Provider("../").rdo_mkt_tp_cd.value;

    //txb_isur_cd.value =  frame.Provider("../").txb_isur_cd.value;

    //txb_outdir_nm.value =  frame.Provider("../").txb_outdir_nm.value;

    //edt_encryp_birthdd.value =  frame.Provider("../").edt_encryp_birthdd.value;

};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Insert = function() {
    if (txb_com_abbrv.getValue() == "" || txb_com_abbrv.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (txb_outdir_nm.getValue() == "" || txb_outdir_nm.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "사외이사명"));
        txb_outdir_nm.focus();
        return;
    }
    //alert(Number(getObjectValue(edt_encryp_birthdd)));
    //alert(getObjectValue(edt_encryp_birthdd));
    //alert(edt_encryp_birthdd.value);


    if ($c.stf.getObjectValue(edt_encryp_birthdd) != "") {
        if (Number($c.stf.getObjectValue(edt_encryp_birthdd)) > $c.ut.cGetToday("yyyymmdd").substring(0, 4)) {
            $c.win.alert("현재 연도보다 출생 연도가 큽니다.");
            edt_encryp_birthdd.focus();
            return;
        }
        if ($c.stf.getObjectValue(edt_encryp_birthdd).length < 4) {
            $c.win.alert("출생연도는 4자리 입니다.");
            edt_encryp_birthdd.focus();
            return;
        }
    }
    dts_outdir.insertRow();
    //dts_outdir.NameValue(1,"MKT_TP_CD") = getObjectValue(rdo_mkt_tp_cd);
    dts_outdir.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isur_cd));
    dts_outdir.setCellData(1, "OUTDIR_NM", $c.stf.getObjectValue(txb_outdir_nm));
    dts_outdir.setCellData(1, "ENCRYP_BIRTHDD", $c.stf.getObjectValue(edt_encryp_birthdd));
    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        trs_outdir.Action = "/OutDir.do?method=registerOutDirInfo&inputMessageId=OUTDIRINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_outdir.KeyName = "toinb_dataid4";
        trs_outdir.KeyValue = "JSP(I:pInput=dts_outdir)";
        trs_outdir.Post();
    }
};




// 시장구분 라디오버튼
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_mkt_tp_cd, js_market);
    if (js_market == "9") {
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
    } else {
        // 콘트롤 잠그기
        //grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        rdo_mkt_tp_cd.setDisabled(true);
    }
};
scwin.trs_outdir_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_outdir_OnFail = function() {
    $c.win.alert('trs_outdir.OnFail() :' + trs_outdir.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_outdir.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=OUTDIRINFO_INOUT";
    dts_outdir.reset();
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);

    //fn_Init();

};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
